//! Output parity between the take-loop's cache keys, seeds and file names
//! in `voxr_narrate` and the JavaScript `voxcpm` they port.
//!
//! The fixture (`tests/fixtures/narration_take_oracle.json`) is checked in
//! and was generated by `tests/tools/narration_oracle/take_files.mjs`,
//! which runs a patched copy of the skill's own `voxcpm` far enough to
//! build and capture its cache-key closures and its `.takes.json` read
//! state, then stops it short of running VoxCPM2 or ffmpeg. Every
//! number in the fixture is a plain JSON number and compares exactly:
//! every case here works in the double range plain `f64` equality holds
//! for.

use std::path::Path;

use serde::Deserialize;
use serde_json::Value;
use voxr_narrate::{
    KeyPart, TakeKeyInput, anchor_key, cache_key, content_hash, prepared_reference_key,
    read_takes_file, ref_id, reference_file, resolve_seed, take_key, voice_file,
};

mod common;
use common::{assert_oracle_current, load_json};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_take_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/take_files.mjs"
);

#[derive(Debug, Deserialize)]
struct Fixture {
    cases: Vec<Value>,
}

fn text<'a>(v: &'a Value, field: &str) -> &'a str {
    v[field]
        .as_str()
        .unwrap_or_else(|| panic!("case {v} field {field} is not a string"))
}

fn opt_text<'a>(v: &'a Value, field: &str) -> Option<&'a str> {
    v[field].as_str()
}

fn number(v: &Value, field: &str) -> f64 {
    v[field]
        .as_f64()
        .unwrap_or_else(|| panic!("case {v} field {field} is not a number"))
}

fn boolean(v: &Value, field: &str) -> bool {
    v[field]
        .as_bool()
        .unwrap_or_else(|| panic!("case {v} field {field} is not a bool"))
}

fn basename(path: &std::path::Path) -> String {
    path.file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_string()
}

/// One `JSON.stringify` array element from the fixture's `parts`, as a
/// [`KeyPart`].
fn key_part(v: &Value) -> KeyPart<'_> {
    match v {
        Value::String(s) => KeyPart::Str(s),
        Value::Number(_) => KeyPart::Num(v.as_f64().unwrap_or(f64::NAN)),
        _ => KeyPart::Null,
    }
}

fn check_hash(case: &Value) {
    let checkpoint = opt_text(case, "checkpoint");
    let voice = text(case, "voice");
    let ref_id = text(case, "refId");
    let parts: Vec<KeyPart<'_>> = case["parts"]
        .as_array()
        .unwrap_or_else(|| panic!("case {case} has no parts array"))
        .iter()
        .map(key_part)
        .collect();
    let want = text(case, "key");
    let got = cache_key(checkpoint, voice, ref_id, &parts);
    assert_eq!(got, want, "hash case {case}");
}

fn check_text_seed(case: &Value) {
    let t = text(case, "text");
    let base = number(case, "base");
    let want = number(case, "seed");
    let got = voxr_narrate::text_seed(t, base);
    assert_eq!(got, want, "textSeed case {case}");
}

fn check_anchor(case: &Value) {
    let checkpoint = opt_text(case, "checkpoint");
    let voice = text(case, "voice");
    let seed = number(case, "seed");
    let language = opt_text(case, "language");
    let want_key = text(case, "anchorKey");
    let got_key = anchor_key(checkpoint, voice, seed, language);
    assert_eq!(got_key, want_key, "anchor key, case {case}");
    let want_file = text(case, "anchorFile");
    let got_file = basename(&voice_file(Path::new(""), &got_key));
    assert_eq!(got_file, want_file, "anchor file, case {case}");
}

fn check_reference(case: &Value) {
    let checkpoint = opt_text(case, "checkpoint");
    let voice = text(case, "voice");
    let ref_id = text(case, "refId");
    assert!(
        case["anchorKey"].is_null(),
        "a reference voice's anchor key must be null, case {case}"
    );
    let key = prepared_reference_key(checkpoint, voice, ref_id);
    let want_clone = text(case, "cloneFrom");
    assert_eq!(
        basename(&reference_file(Path::new(""), &key)),
        want_clone,
        "cloneFrom, case {case}"
    );
    let content = text(case, "content");
    let want_prepared = text(case, "prepared");
    assert_eq!(
        content_hash(content.as_bytes()),
        want_prepared,
        "prepared marker, case {case}"
    );
}

fn check_take(case: &Value) {
    let anchor_key_field = &case["anchorKey"];
    let anchor_key = anchor_key_field.as_str();
    let voice = text(case, "voice");
    let style = text(case, "style");
    let file_text = text(case, "text");
    let seed = number(case, "seed");
    let cfg = number(case, "cfg");
    let steps = number(case, "steps");
    let hifi = boolean(case, "hifi");
    let want = text(case, "takeFile");
    // A reference-cloned take (anchorKey null) was made with a reference recording; its ref id is the one the
    // "reference" case fixed. A designed voice's take carries no reference id.
    let key = take_key(
        None,
        voice,
        if anchor_key.is_none() {
            "/rec with spaces.wav:12345:1699999999999.25"
        } else {
            ""
        },
        TakeKeyInput {
            anchor_key,
            style,
            text: file_text,
            seed,
            cfg,
            steps,
            hifi,
        },
    );
    assert_eq!(format!("{key}.wav"), want, "take file, case {case}");
}

fn check_takes_read(case: &Value) {
    let raw = case["raw"].as_str();
    let asked = case["asked"].as_f64();
    let config_seed = case["configSeed"].as_f64();
    let read = read_takes_file(raw.unwrap_or("__oracle_no_file__"));
    let want_current = boolean(case, "current");
    assert_eq!(read.seed.is_some(), want_current, "current, case {case}");
    let resolved = resolve_seed(asked, &read, config_seed);
    assert_eq!(
        resolved.seed,
        number(case, "seed"),
        "resolved seed, case {case}"
    );
    let want_before = number(case, "before");
    let before = read
        .seed
        .or(config_seed)
        .unwrap_or(voxr_narrate::DEFAULT_SEED);
    assert_eq!(before, want_before, "before, case {case}");
    // A foreign document read as a flat map keeps every key in the skill (`chosen = saved`, untyped), but the port's
    // `takes` only ever holds seeds: a non-numeric value is dropped rather than kept as a broken seed.
    let chosen = voxr_narrate::chosen_takes(read, &resolved);
    let want_chosen = case["chosen"]
        .as_object()
        .unwrap_or_else(|| panic!("case {case} has no chosen object"));
    let want_numeric: Vec<(&String, f64)> = want_chosen
        .iter()
        .filter_map(|(k, v)| v.as_f64().map(|n| (k, n)))
        .collect();
    assert_eq!(
        chosen.len(),
        want_numeric.len(),
        "chosen length, case {case}"
    );
    for (k, want_seed) in want_numeric {
        assert_eq!(
            chosen.get(k).copied(),
            Some(want_seed),
            "chosen[{k:?}], case {case}"
        );
    }
}

#[test]
fn matches_javascript_on_every_case() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    for case in &fixture.cases {
        match text(case, "case") {
            "hash" => check_hash(case),
            "textSeed" => check_text_seed(case),
            "anchor" => check_anchor(case),
            "reference" => check_reference(case),
            "take" => check_take(case),
            "takesRead" => check_takes_read(case),
            other => panic!("fixture names an unknown case {other:?}"),
        }
    }
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}

/// [`ref_id`]'s own format, independent of the fixture: `path:size:mtimeMs`.
#[test]
fn ref_id_matches_the_fixtures_reference_case() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    let case = fixture
        .cases
        .iter()
        .find(|c| text(c, "case") == "reference")
        .unwrap_or_else(|| panic!("fixture has no reference case"));
    assert_eq!(
        ref_id("/rec with spaces.wav", 12345, 1_699_999_999_999.25),
        text(case, "refId"),
    );
}
